#### P1162 填涂颜色
https://www.luogu.com.cn/problem/P1162
```cpp
int n;
int dx[4] = { 1, -1, 0, 0 };
int dy[4] = { 0, 0, 1, -1 };

void dfs(int x, int y, vector<vector<int>>& matrix, vector<vector<bool>>& outside) {
	if(x < 0 || x >= n || y < 0 || y >= n)
		return;
	if(matrix[x][y] == 1)
		return;
	if(outside[x][y])
		return;

	outside[x][y] = true;
	for(int i = 0; i < 4; i++) {
		dfs(x + dx[i], y + dy[i], matrix, outside);
	}
}

int main() {
	cin >> n;
	vector<vector<int>>	 matrix(n, vector<int>(n));
	vector<vector<bool>> outside(n, vector<bool>(n, false));

	for(int i = 0; i < n; i++) {
		for(int j = 0; j < n; j++) {
			cin >> matrix[i][j];
		}
	}
	// mark
	for(int i = 0; i < n; i++) {
		if(matrix[i][0] == 0)
			dfs(i, 0, matrix, outside);
		if(matrix[i][n - 1] == 0)
			dfs(i, n - 1, matrix, outside);
		if(matrix[0][i] == 0)
			dfs(0, i, matrix, outside);
		if(matrix[n - 1][i] == 0)
			dfs(n - 1, i, matrix, outside);
	}

	for(int i = 0; i < n; i++) {
		for(int j = 0; j < n; j++) {
			if(matrix[i][j] == 0 && !outside[i][j]) {
				matrix[i][j] = 2;
			}
		}
	}

	for(int i = 0; i < n; i++) {
		for(int j = 0; j < n; j++) {
			cout << matrix[i][j];
			if(j != n - 1)
				cout << ' ';
		}
		cout << endl;
	}

	return 0;
}
```
典型 dfs，需要注意的是给所有外部的方块添上颜色的时候要从**整张地图边缘开始遍历**，同样可以使用 BFS 解法->

